static boolean isPrime(int n) {
    if (n < 2) return false;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) return false;
    }
    return true;
}

public static void main(String[] args) {
    Stream.iterate(2, n -> n + 1)
          .filter(Exercise23_PrimeGenerator::isPrime)
          .limit(20)
          .forEach(n -> System.out.print(n + " "));
}

